body {
  background:
    radial-gradient(circle at 20% 16%, color-mix(in srgb, var(--waki-accent) 9%, transparent), transparent 30%), radial-gradient(circle at 80% 20%, color-mix(in srgb, var(--waki-accent-2) 7%, transparent), transparent 32%), linear-gradient(118deg, transparent 0 30%, color-mix(in srgb, white 8%, transparent) 42%, transparent 56%),
    radial-gradient(circle at 8% 10%, var(--waki-blob-1), transparent 32%),
